const b = box(40,30,20)
const c = move(b,[60,0,0],{copy:true})
round(c.edge('top','right'), 2)

const a = box(30,30,10)
const b = box(20,20,20,{at:[10,0,5]})
const u = join(a,b)
round(a.edge('bottom','left'), 2)

const b = box(40,30,20)
hole(b,{across:6})
hollow(b,{wall:2, open:'bottom'})

const b = box(40,30,20)
hollow(b,{wall:3, open:'top'})
round(b.edge('top','right'), 1)

const b = box(40,30,20)
round(b.edge('bottom','left'), 2)
hollow(b,{wall:2, open:'top'})

const b = box(10,10,10)
repeat(b,{count:3, step:[15,0,0]})
round(b.edge('top','right'), 1)

const b = box(10,10,10,{at:[20,0,0]})
repeatAround(b,{count:4, axis:'z'})
round(b.edge('top','front'), 1)
